12: const withBearerAndInstitutionId: WithDefaultsT<'bearerAuth'> =
13:   (wrappedOperation) => (params: any) => {
14:     const token = storageTokenOps.read();
15:     return wrappedOperation({
16:       ...params,
17:       bearerAuth: `Bearer ${token}`,
18:     });
19:   };
20: 
21: const apiClient = createClient({
22:   baseUrl: ENV.URL_API.API_ONBOARDING_V2,
23:   basePath: '',
24:   fetchApi: buildFetchApi(ENV.API_TIMEOUT_MS.DASHBOARD),
25:   withDefaults: withBearerAndInstitutionId,
26: });
27: 
28: const buildOnSuccess = () => `${window.location.pathname}${window.location.search}`;
29: 
30: const buildRedirectUrl = (baseUrl: string) => {
31:   const [urlWithoutHash, hashFragment] = baseUrl.split('#');
32:   const separator = urlWithoutHash.includes('?') ? '&' : '?';
33:   const onSuccess = encodeURIComponent(buildOnSuccess());
34:   const hash = hashFragment ? `#${hashFragment}` : '';
35:   // eslint-disable-next-line sonarjs/no-nested-template-literals
36:   return `${urlWithoutHash}${separator}onSuccess=${onSuccess}${hash}`;
37: };
