85:     type: string,
86:     name?: string
87:   ): Promise<Response> => {
88:     const token = storageTokenOps.read();
89:     const params = new URLSearchParams({ type });
90:     if (name) {
91:       params.append('name', name);
92:     }
93:     return fetch(
94:       `${ENV.URL_API.API_ONBOARDING_V2}/v2/tokens/${onboardingId}/download?${params.toString()}`,
95:       {
96:         method: 'GET',
97:         headers: {
98:           accept: '*/*',
99:           'accept-language': 'it-IT,it;q=0.9,en-US;q=0.8,en;q=0.7',
100:           authorization: `Bearer ${token}`,
