107:   getAvailableDocuments: async (onboardingId: string): Promise<AvailableDocumentsResource> => {
108:     const result = await apiClient.getAvailableDocumentsUsingGET({
109:       onboardingId,
110:     });
111:     return extractResponse(result, 200, onRedirectToBackstage);
112:   },
